<script>
async function ownerShare(channel){
    const message=@json($shareMessage), email=@json($capitalOwner->email), phone=@json(preg_replace('/\D+/', '', (string)$capitalOwner->phone));
    if(channel==='whatsapp'){ if(!phone)return Swal.fire('No phone','This owner has no phone number.','info'); window.open(`https://wa.me/${phone}?text=${encodeURIComponent(message)}`,'_blank'); }
    if(channel==='email' && !email)return Swal.fire('No email','This owner has no email address.','info');
    if(channel==='sms' && !phone)return Swal.fire('No phone','This owner has no phone number.','info');
    if(!['email','sms'].includes(channel))return;
    const result=await Swal.fire({title:`Send by ${channel.toUpperCase()}?`,text:channel==='email'?`Brevo will send to ${email}.`:`SMS will be sent to ${phone}.`,icon:'question',showCancelButton:true,confirmButtonText:'Send'});
    if(!result.isConfirmed)return;
    Swal.fire({title:'Sending…',allowOutsideClick:false,didOpen:()=>Swal.showLoading()});
    try{
        const response=await fetch(@json(route('role.financing.capital.send',['role'=>$role])),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':@json(csrf_token())},body:JSON.stringify({owner_id:@json($capitalOwner->id),channel,date_from:@json(request('date_from')),date_to:@json(request('date_to'))})});
        const data=await response.json();
        Swal.fire(data.success?'Sent':'Not sent',data.message||'Unable to send.',data.success?'success':'error');
    }catch(error){Swal.fire('Not sent',error.message||'Unable to send.','error');}
}
</script>
